--
-- Struktura tabulky `contact_messages`
--

CREATE TABLE `contact_messages` (
  `id` int(11) NOT NULL,
  `name` varchar(255) NOT NULL,
  `email` varchar(255) NOT NULL,
  `message` text NOT NULL,
  `language` varchar(5) NOT NULL DEFAULT 'en',
  `ip_address` varchar(45) NOT NULL,
  `user_agent` text DEFAULT NULL,
  `browser_name` varchar(100) DEFAULT NULL,
  `browser_version` varchar(50) DEFAULT NULL,
  `operating_system` varchar(100) DEFAULT NULL,
  `device_type` varchar(50) DEFAULT NULL,
  `screen_resolution` varchar(20) DEFAULT NULL,
  `time_on_site` int(11) DEFAULT NULL COMMENT 'Čas strávený na webu v sekundách',
  `referrer` varchar(500) DEFAULT NULL,
  `country_code` varchar(5) DEFAULT NULL,
  `country_name` varchar(100) DEFAULT NULL,
  `city` varchar(100) DEFAULT NULL,
  `timezone` varchar(50) DEFAULT NULL,
  `session_id` varchar(128) DEFAULT NULL,
  `csrf_token_used` varchar(128) DEFAULT NULL,
  `is_processed` tinyint(1) DEFAULT 0 COMMENT '0 = nová, 1 = zpracovaná',
  `email_sent` tinyint(1) DEFAULT 0 COMMENT '0 = email neodeslán, 1 = email odeslán',
  `spam_score` decimal(3,2) DEFAULT 0.00 COMMENT 'Skóre podezření na spam (0.00-1.00)',
  `notes` text DEFAULT NULL COMMENT 'Interní poznámky',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

