  `cover_path` varchar(255) DEFAULT NULL,
  `pdf_path` varchar(255) DEFAULT NULL COMMENT 'Cesta k PDF souboru pro tento jazyk, např. assets/downloads/ebooks/nis2_guide_cz.pdf'
