INSERT INTO `ebook_translations` (`id`, `ebook_id`, `lang_code`, `title`, `description`, `meta_title`, `meta_description`, `cover_path`, `pdf_path`) VALUES
(4, 2, 'en', 'NIS2 Directive Guide: Essential Summary and Preparation', '<p>Download our comprehensive guide to the NIS2 Directive. Understand the new obligations for ensuring cybersecurity in your organization, who is affected, and how to effectively prepare for its implementation. This e-book provides key information and practical steps. (Full e-book content currently available in Czech).</p>', 'NIS2 Guide | Obligations and Preparation | Pietro Dubsky', 'A comprehensive guide to the NIS2 Directive. Learn key obligations, impacts, and how to prepare for the new European cybersecurity legislation. (Content in CZ)', 'assets/images/ebook_covers/nis2_cover_en.png', 'assets/downloads/ebooks/nis2-sprava-a-nasaseni_en_1747214146_NIS2_Prirucka_CZ.pdf'),
(5, 2, 'cz', 'Průvodce směrnicí NIS2: Základní shrnutí a příprava', '<p>St&aacute;hněte si na&scaron;eho komplexn&iacute;ho průvodce směrnic&iacute; NIS2. Zjistěte, jak&eacute; nov&eacute; povinnosti přin&aacute;&scaron;&iacute; pro zaji&scaron;těn&iacute; kybernetick&eacute; bezpečnosti ve va&scaron;&iacute; organizaci, koho se t&yacute;k&aacute; a jak se efektivně připravit na jej&iacute; implementaci. Tento e-book v&aacute;m poskytne kl&iacute;čov&eacute; informace a praktick&eacute; kroky.</p>', 'NIS2 Průvodce | Povinnosti a Příprava | Pietro Dubsky', 'Komplexní průvodce směrnicí NIS2. Zjistěte klíčové povinnosti, dopady a jak se připravit na novou evropskou legislativu o kybernetické bezpečnosti.', 'assets/images/ebook_covers/nis2_cover_cz.png', 'assets/downloads/ebooks/nis2-sprava-a-nasaseni_cz_1747214146_NIS2_Prirucka_CZ.pdf'),
(6, 2, 'it', 'Guida alla Direttiva NIS2: Sintesi Essenziale e Preparazione', '<p>Scarica la nostra guida completa alla Direttiva NIS2. Comprendi i nuovi obblighi per garantire la cibersicurezza nella tua organizzazione, chi &egrave; interessato e come prepararsi efficacemente alla sua implementazione. Questo e-book fornisce informazioni chiave e passaggi pratici. (Contenuto completo dell\'e-book attualmente disponibile in ceco).</p>', 'Guida NIS2 | Obblighi e Preparazione | Pietro Dubsky', 'Una guida completa alla Direttiva NIS2. Impara gli obblighi chiave, gli impatti e come prepararsi alla nuova legislazione europea sulla cibersicurezza. (Contenuto in CZ)', 'assets/images/ebook_covers/nis2_cover_it.png', 'assets/downloads/ebooks/nis2-sprava-a-nasaseni_it_1747214146_NIS2_Prirucka_CZ.pdf');

